from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    store = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        if key not in store:
            return True
        _, wt = store[key]
        return t >= wt + ttl

    for op in ops:
        kind, t = op[0], op[1]
        if kind == 'put':
            key, value = op[2], op[3]
            if key in store:
                if is_expired(key, t):
                    del store[key]
                else:
                    del store[key]
            if key not in store and len(store) >= capacity:
                # evict LRU, but only if it counts as present; expired ones removed lazily
                # remove expired entries first if any at front
                while store:
                    oldest_key = next(iter(store))
                    if is_expired(oldest_key, t):
                        del store[oldest_key]
                    else:
                        break
                if len(store) >= capacity:
                    store.popitem(last=False)
            store[key] = (value, t)
            store.move_to_end(key)
        elif kind == 'get':
            key = op[2]
            if key in store and not is_expired(key, t):
                value, wt = store[key]
                store.move_to_end(key)
                results.append(value)
            else:
                if key in store:
                    del store[key]
                results.append(-1)
    return results

